{"fw_ld6_walk_civ_1_0002","walk",3,"reg=civilian,family,worker,rescue",{1,"Slow down, I've got a blister",2,"We can't stop here",1,"Then slow down without stopping",3,"I'll slow down for the both of you, I'm dying"}},
