{"fw_ld6_walk_civ_1_0012","walk",3,"reg=civilian,family,worker,rescue",{1,"You're stepping on my heel",2,"Then walk faster",1,"I'm walking fast",3,"Both of you, walk like adults"}},
{"fw_ld6_walk_civ_1_0013","walk",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"Why are you running",2,"I'm not running",1,"You're doing the fast walk, the walk where your arms go",3,"It's the I-have-to-pee walk"}},
{"fw_ld6_walk_civ_1_0014","walk",2,"reg=civilian,family,worker,rescue",{1,"Slow down for the old man",2,"I'm not old",1,"You're sixty-three, that's old",2,"I'm sixty-three and I can still beat you to the corner"}},
{"fw_ld6_walk_civ_1_0015","walk",2,"reg=civilian,family,worker,rescue",{1,"How much farther?",2,"Not far",1,"That's what you said an hour ago",2,"I know what I said, I was being optimistic"}},
{"fw_ld6_walk_civ_1_0016","walk",3,"reg=civilian,family,worker,rescue",{1,"Are we close?",2,"Closer",1,"Closer than what?",3,"Closer than before, shut up and walk"}},
{"fw_ld6_walk_civ_1_0017","walk",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Are we there yet?",2,"Don't start",1,"I'm just asking",2,"You're a grown person"}},
{"fw_ld6_walk_civ_1_0018","walk",2,"reg=civilian,family,worker,rescue",{1,"Which way?",2,"Left",1,"You said left last time",2,"And it was left, wasn't it"}},
{"fw_ld6_walk_civ_1_0019","walk",3,"reg=civilian,family,worker,rescue",{1,"Which way, left or right?",2,"Right, I'm right-handed, it's the only direction I trust",3,"I'm left-handed, so we're going left"}},
{"fw_ld6_walk_civ_1_0020","walk",3,"reg=civilian,family,worker,rescue",{1,"I know a shortcut",2,"Your shortcuts take an hour",1,"This one's different",3,"They're all different, that's why they take an hour"}},
{"fw_ld6_walk_civ_1_0021","walk",3,"reg=civilian,family,worker,rescue|mood=funny|world=building",{1,"Did we pass that mailbox already?",2,"We passed a mailbox",1,"It's the same mailbox, it's got a dent on the side",3,"Everybody's mailbox has a dent"}},
{"fw_ld6_walk_civ_1_0022","walk",3,"reg=civilian,family,worker,rescue",{1,"Cut through the field?",2,"It's all grass up to my waist",1,"I'll go first",3,"If there's anything in there, you're finding it first"}},
{"fw_ld6_walk_civ_1_0023","walk",2,"reg=civilian,family,worker,rescue",{1,"Past the next bend",2,"You said that three bends ago",1,"This is the next one",2,"There's always a next one"}},
