{"fw_ld6_walk_civ_1_0025","walk",3,"reg=civilian,family,worker,rescue",{1,"Is it left or right at the sign?",2,"It's left",3,"It's right",2,"Fine, somebody flip a coin"}},
{"fw_ld6_walk_civ_1_0026","walk",2,"reg=civilian,family,worker,rescue|world=road",{1,"We've been on this road forever",2,"It's been an hour",1,"It's been a forever hour"}},
{"fw_ld6_walk_civ_1_0027","walk",3,"reg=civilian,family,worker,rescue",{1,"I thought it was closer",2,"Past the church. It's right there",1,"That's what you said about the last church",3,"This is Kentucky. You can't just say 'the church'"}},
{"fw_ld6_walk_civ_1_0028","walk",2,"reg=civilian,family,worker,rescue",{1,"My feet are killing me",2,"Boots off at the next stop",1,"If I take them off I'm never getting them back on"}},
{"fw_ld6_walk_civ_1_0029","walk",3,"reg=civilian,family,worker,rescue",{1,"My back's gone",2,"Your back's been gone since breakfast",1,"It's gone further",3,"Mine went with the pack, it's not coming back"}},
{"fw_ld6_walk_civ_1_0030","walk",2,"reg=civilian,family,worker,rescue",{1,"I need a break",2,"We just had a break",1,"That was ten minutes ago",2,"Ten minutes ago is a long time, I admit"}},
{"fw_ld6_walk_civ_1_0031","walk",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"I'm so thirsty my tongue's a sock",2,"Here, don't swallow it all",1,"It's gone",3,"Of course it's gone"}},
