{"fw_ld6_walk_civ_1_0037","walk",3,"reg=civilian,family,worker,rescue",{1,"Hungry",2,"You're always hungry",1,"I'm always hungry because I'm always walking",3,"That's a fair point"}},
{"fw_ld6_walk_civ_1_0038","walk",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"You got any gum?",2,"Half a stick",1,"I'll take the half",2,"Don't chew it all, it's the last half"}},
