{"fw_ld6_walk_civ_1_0045","walk",3,"reg=civilian,family,worker,rescue|mood=funny",{1,"It's just me, don't shoot",2,"Where the hell did you come from?",1,"I stopped to tie my shoe",3,"Say something next time"}},
